import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class FloodFillDemo {

    private static final Logger log = Logger.getLogger(FloodFillDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // 1 = low risk, 2 = medium risk, 3 = high risk.
        int[][] riskGrid = {
                {2, 2, 2, 1},
                {2, 2, 1, 1},
                {1, 2, 2, 3}
        };

        Account priya = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        RiskZoneFiller filler = new RiskZoneFiller();

        log.info(() -> priya.getHolderName() + " escalating connected medium zone from [0][0]:");
        for (int[] row : riskGrid) log.info(() -> Arrays.toString(row));

        filler.floodFillDfs(riskGrid, 0, 0, 3);   // escalate medium (2) block to high (3)

        log.info("Grid after escalation:");
        for (int[] row : riskGrid) log.info(() -> Arrays.toString(row));
    }
}

