class RiskZoneFiller {

    private static final Logger log = Logger.getLogger(RiskZoneFiller.class.getName());

    // Depth-first flood fill starting at (sr, sc), repainting connected same-value cells.
    void floodFillDfs(int[][] grid, int sr, int sc, int newValue) {
        int original = grid[sr][sc];
        if (original == newValue) {
            log.warning("new value equals original; nothing to do");
            return;                                 // avoid infinite recursion
        }
        dfs(grid, sr, sc, original, newValue);
    }

    private void dfs(int[][] grid, int r, int c, int original, int newValue) {
        if (r < 0 || r >= grid.length || c < 0 || c >= grid[0].length) return;
        if (grid[r][c] != original) return;         // boundary or different zone
        grid[r][c] = newValue;                      // repaint before recursing
        log.fine(() -> "repaint [" + r + "][" + c + "] -> " + newValue);
        dfs(grid, r + 1, c, original, newValue);
        dfs(grid, r - 1, c, original, newValue);
        dfs(grid, r, c + 1, original, newValue);
        dfs(grid, r, c - 1, original, newValue);
    }

    // Breadth-first flood fill: same result, uses a queue instead of recursion.
    void floodFillBfs(int[][] grid, int sr, int sc, int newValue) {
        int original = grid[sr][sc];
        if (original == newValue) return;
        Deque<int[]> queue = new ArrayDeque<>();
        grid[sr][sc] = newValue;
        queue.add(new int[]{sr, sc});
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            for (int[] d : dirs) {
                int nr = cell[0] + d[0];
                int nc = cell[1] + d[1];
                if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length
                        && grid[nr][nc] == original) {
                    grid[nr][nc] = newValue;        // mark at enqueue time
                    queue.add(new int[]{nr, nc});
                }
            }
        }
    }
}

